                            product_name_snapshot, bom_id, route_id, plan_qty, completed_qty, good_qty,
                            defect_qty, status, priority, plan_start_time, plan_end_time, actual_start_time,
                            actual_end_time, created_at, remark) VALUES
(2000, 'WO-HIST-001', NULL, 1, 'TV-AOC-55U4K-001', 'AOC 55 英寸 4K 智能电视 Demo', 1, 1,
 1400, 1400, 1346, 54, 'COMPLETED', 'NORMAL',
 DATE_SUB(CURDATE(), INTERVAL 16 DAY) + INTERVAL 8 HOUR,
 DATE_SUB(CURDATE(), INTERVAL 1 DAY) + INTERVAL 18 HOUR,
 DATE_SUB(CURDATE(), INTERVAL 16 DAY) + INTERVAL 8 HOUR,
 DATE_SUB(CURDATE(), INTERVAL 1 DAY) + INTERVAL 18 HOUR,
 DATE_SUB(CURDATE(), INTERVAL 16 DAY) + INTERVAL 8 HOUR,
 '第 7 周种子：近 14 天历史生产数据（AI 周报趋势/环比演示）');
